--
-- Table structure for table `mutations`
--

DROP TABLE IF EXISTS `mutations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mutations` (
  `mutation_id` int(11) NOT NULL AUTO_INCREMENT,
  `immatriculation_id` int(11) DEFAULT NULL,
  `motif` varchar(255) DEFAULT NULL,
  `ministere` int(11) DEFAULT NULL COMMENT 'Nouveau Ministère',
  `direction` int(11) DEFAULT NULL COMMENT 'Nouvelle direction',
  `status` smallint(6) DEFAULT 0 COMMENT '0 = en attente,1=valider,2=rejeter',
  `fonction` varchar(85) DEFAULT NULL,
  `ancienMinistere_id` int(11) DEFAULT NULL,
  `ancienDirection_id` int(11) DEFAULT NULL,
