--
-- Table structure for table `vehicules`
--

DROP TABLE IF EXISTS `vehicules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vehicules` (
  `vehicule_id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `marque_id` int(11) NOT NULL,
  `model_id` int(11) NOT NULL,
  `genre` int(11) NOT NULL,
  `typeVehicule` int(11) NOT NULL,
  `numChassie` varchar(20) NOT NULL,
  `carosserie` varchar(20) NOT NULL,
  `placeNumberAssis` smallint(6) NOT NULL DEFAULT 0,
  `placeNumberDebout` smallint(6) NOT NULL DEFAULT 0,
  `nbPorte` smallint(6) NOT NULL DEFAULT 0,
  `kilometrage` int(11) NOT NULL DEFAULT 0,
  `cylinderNumber` int(11) NOT NULL DEFAULT 0,
  `nbreEssuie` int(11) DEFAULT 0,
  `pv` int(11) DEFAULT 0,
  `cu` int(11) DEFAULT 0,
  `pa` int(11) DEFAULT 0 COMMENT 'Puissance Administrative en Cheval Vapeur comme unité de mesure',
  `madeYear` int(11) NOT NULL DEFAULT 1900,
  `releaseYear` date DEFAULT NULL,
  `energy` varchar(50) NOT NULL,
  `transmission` varchar(45) DEFAULT NULL,
  `provenance` varchar(70) NOT NULL,
  `colorVehicule` varchar(50) NOT NULL,
  `acquisition` varchar(30) NOT NULL,
  `lettreImage` varchar(255) DEFAULT NULL,
  `faceImage` varchar(255) DEFAULT NULL,
  `profileImage` varchar(255) DEFAULT NULL,
  `backImage` varchar(255) DEFAULT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`vehicule_id`),
  UNIQUE KEY `numChassie_UNIQUE` (`numChassie`)
) ENGINE=InnoDB AUTO_INCREMENT=430 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

